// Server-owned runtime constraints and immutable decision evidence. Callers must
// supply trusted user intent, not metadata generated by an agent proposal.
const FIELDS = ['tool', 'provider', 'model', 'effort'];
const text = (v) => typeof v === 'string' ? v.trim() : '';
const obj = (v) => v && typeof v === 'object' && !Array.isArray(v) ? v : {};
const fail = (code, message) => Object.assign(new Error(message), { code, statusCode: 422 });
const canonical = (field, value) => ['tool', 'effort'].includes(field) ? text(value).toLowerCase() : text(value);

export function normalizeUserRuntimeConstraints(value = {}) {
  const source = obj(value);
  const result = {};
  for (const field of FIELDS) {
    const entry = source[field];
    if (entry === undefined) continue;
    if (!entry || typeof entry !== 'object' || !['locked', 'preferred'].includes(entry.mode)
        || !text(entry.value) || !text(entry.source) || !text(entry.scope)
        || !Number.isSafeInteger(entry.version) || entry.version < 1) {
      throw fail('ORG_RUNTIME_CONSTRAINT_INVALID', `Invalid ${field} constraint`);
    }
    result[field] = { value: canonical(field, entry.value), mode: entry.mode,
      source: text(entry.source), scope: text(entry.scope), version: entry.version };
  }
  return result;
}

export function assertRuntimeConstraints(runtime, constraints = {}) {
  const normalized = normalizeUserRuntimeConstraints(constraints);
  for (const [field, constraint] of Object.entries(normalized)) {
    const actual = field === 'provider' ? runtime?.provider || runtime?.providerProfile : runtime?.[field];
    if (constraint.mode === 'locked' && canonical(field, actual) !== constraint.value) {
      throw fail('ORG_RUNTIME_USER_LOCKED', `Selected ${field} conflicts with the user's locked constraint`);
    }
  }
  return normalized;
}

// Candidate evidence is observational. Unknown/stale is retained as unknown;
// it never becomes a free price, a healthy provider, or proof of availability.
export function filterRuntimeCandidates(candidates = [], { constraints = {}, budget = null, now = Date.now() } = {}) {
  const normalized = normalizeUserRuntimeConstraints(constraints);
  if (!Array.isArray(candidates)) throw fail('ORG_RUNTIME_CANDIDATES_INVALID', 'Candidates must be an array');
  return candidates.flatMap((candidate) => {
    const runtime = obj(candidate?.runtime);
    if (['tool', 'provider', 'model'].some((field) => !canonical(field, field === 'provider' ? runtime.provider || runtime.providerProfile : runtime[field]))) return [];
    try { assertRuntimeConstraints(runtime, normalized); } catch { return []; }
    const evidence = obj(candidate.evidence);
    const expires = Date.parse(evidence.expiresAt || '');
    const fresh = Number.isFinite(expires) && expires > now;
    const availability = fresh && ['available', 'unavailable'].includes(evidence.availability) ? evidence.availability : 'unknown';
    if (availability === 'unavailable') return [];
    const cost = obj(candidate.cost);
    const amount = Number.isFinite(cost.amount) && cost.amount >= 0 ? cost.amount : null;
    const costKnown = amount !== null && text(cost.currency) && text(cost.source) && ['actual', 'estimate'].includes(cost.kind)
      && Number.isFinite(Date.parse(cost.expiresAt || '')) && Date.parse(cost.expiresAt) > now;
    if (budget && costKnown && text(budget.currency) === text(cost.currency)
        && Number.isFinite(budget.remaining) && amount > budget.remaining) return [];
    return [{ ...candidate, evidence: { ...evidence, availability },
      cost: costKnown ? { ...cost, amount } : { kind: 'unknown' } }];
  });
}

export function createRuntimeSelectionRecord({ runtime, constraints = {}, evidence = null, rationale = '', cost = null } = {}) {
  const requestedConstraints = assertRuntimeConstraints(runtime, constraints);
  return { schemaVersion: 1, requestedConstraints, selected: { ...runtime },
    evidence: evidence && typeof evidence === 'object' ? structuredClone(evidence) : null,
    cost: cost && typeof cost === 'object' ? structuredClone(cost) : { kind: 'unknown' },
    rationale: text(rationale).slice(0, 2000), actual: null };
}

// Expand only provider associations actually present in the catalog; do not
// invent a provider/model combination or infer health from a configured entry.
export function runtimeCandidatesFromCatalog(catalog = []) {
  if (!Array.isArray(catalog)) return [];
  const result = [];
  for (const entry of catalog) {
    for (const model of Array.isArray(entry?.models) ? entry.models : []) {
      const modelId = text(model?.id);
      if (!modelId) continue;
      const separator = modelId.lastIndexOf('@');
      const scoped = separator > 0 ? modelId.slice(separator + 1) : '';
      const providers = scoped ? [scoped] : (entry.providers?.length === 1 ? entry.providers : []);
      const levels = Array.isArray(model.effortLevels) && model.effortLevels.length ? model.effortLevels : entry.effortLevels;
      for (const provider of providers) for (const effort of Array.isArray(levels) && levels.length ? levels : ['']) {
        result.push({ runtime: { tool: entry.tool, provider, model: modelId, ...(effort ? { effort } : {}) },
          evidence: { availability: 'unknown', source: 'runtime_catalog' }, cost: { kind: 'unknown' } });
      }
    }
  }
  return result;
}
